#!/usr/bin/env python3
"""check-gen: every generated file must equal what its generator produces.

The Lean counterpart of the Rocq Makefile's `check-decode` / `check-ucode`
(regenerate, then fail if anything moved), for the generated files of this
tree.  A diff means one of two things: an INPUT moved (a re-dumped image, a
regenerated model) and the derived file was not regenerated with it -- the
proofs are then about a stale copy -- or somebody HAND-EDITED a generated
file, and the edit is about to be lost.

Nothing in the tree is modified: every generator runs in a scratch directory
against copies of its inputs, and its output is diffed against the checked-in
file.

WHAT IS CHECKED (always; pure Python, no toolchain):

  model-facts    MachCSL/ModelFacts.lean      = tools/gen_model_facts.py (model/…/PlatformConfig.lean)
  platform       MachCSL/Platform.lean        = tools/gen_platform.py (model/…/LeanRV64D.lean)
  kernel-tree    Xv6/KernelTree.lean          = tools/gen_text_tree.py (Xv6/KernelImage.lean)
  user-text:<P>  Xv6/User/<P>{Tree,Text}.lean = tools/gen_user_text.py (Xv6/User/<P>Image.lean)
  fs-img         Xv6/FsImgRaw.lean            = tools/dump_fs_image.py (the image the file itself spells,
                                                 whose md5 must be the one its header records)
  user-elf:<P>   Xv6/User/<P>ElfRaw.lean spells a file whose md5 is the one the
                 headers of <P>ElfRaw.lean and <P>Image.lean record
  pins           the revision / md5 pins in the generated headers agree with one another

WITH `riscv64-linux-gnu-objdump` on PATH (any machine with riscv64 binutils
has it; a runner without it reports SKIP, or FAIL under --strict):

  user-elf:<P>   additionally Xv6/User/<P>{Image,ElfRaw,Tree,Text}.lean
                 = tools/dump_user_elf.py run on the ELF that <P>ElfRaw.lean spells.
                 The user ELFs are not checked in as files, but <P>ElfRaw.lean IS
                 the file, byte for byte, so the input is derivable.

WITH THE KERNEL ELF (`--kernel PATH`, default xv6-riscv/kernel/kernel if it
exists and is the pinned build) and objdump:

  kernel         Xv6/KernelImage.lean, Xv6/KernelTree.lean, the byte lists of
                 Xv6/KernelData.lean and MachCSL/KernelElf.lean
                 = tools/dump_kernel.py, tools/gen_kernel_data.py, tools/dump_elf_image.py

WHAT IS NOT CHECKED HERE, AND WHY (the same exclusions as Rocq's ci.yml):

  * the kernel dumps in CI: the kernel ELF is not checked in (xv6-riscv/ is
    .gitignored and CI never builds it), and unlike the user programs the
    tree holds only its loaded segment, not the file.  The three dumps are
    checked AGAINST EACH OTHER by the build (`Xv6.bootImage_wf`), and
    `make check-gen-kernel` is the by-hand check when an ELF is at hand.
  * model/Lean_RV64D/: regenerating it needs the patched `sail` compiler
    (tools/regen_sail_model.sh); by hand, rerun that script and
    `git diff --exit-code model/`.
  * Xv6/Ush*Code.lean: written once by a lane script that was not kept, then
    re-pointed by tools/sh_rebase (a one-off migration, not a generator).
    Every fact in them is re-proved from the image by the build.

Usage:
    tools/check_gen.py [--format text|md] [--strict] [--kernel PATH]
                       [--objdump NAME] [--only CHECK ...] [--keep DIR]
Exit status: 1 if any check FAILs, else 0.
"""
import argparse
import difflib
import hashlib
import os
import re
import shutil
import subprocess
import sys
import tempfile

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
USER_PROGS = ["Cat", "Echo", "Grep", "Init", "Seccomp", "Sh", "Sync"]
ROW = 32
BSIZE = 1024

OK, FAIL, SKIP = "ok", "FAIL", "skip"

HEADER_RE = re.compile(
    r"^-- AUTO-GENERATED by (\S+) from (\S+) \(xv6-riscv (.*?)(?:, md5 ([0-9a-f]{32}))?\); do not edit\.")


def _read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def _read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def _write(path, data):
    with open(path, "wb") as f:
        f.write(data)


def header(path):
    """(generator, source, rev, md5 or None) from a generated file's first line."""
    with open(path, encoding="utf-8") as f:
        m = HEADER_RE.match(f.readline())
    if not m:
        raise ValueError(f"{path}: first line is not an AUTO-GENERATED header with a revision")
    return m.groups()


# ---------------------------------------------------------------------------
# reading the raw images back out of their Lean spelling
# ---------------------------------------------------------------------------

def _rows(src, defname):
    """The Nat literals of every `def <defname>N : List Nat := [ ... ]`, in order of N."""
    pages = {}
    for m in re.finditer(r"def %s(\d+) : List Nat := \[\n(.*?)\n\]" % re.escape(defname), src, re.S):
        vals = []
        for line in m.group(2).split("\n"):
            tok = line.split("--")[0].strip().rstrip(",")
            if tok:
                vals.append(int(tok, 16) if tok.startswith("0x") else int(tok))
        pages[int(m.group(1))] = vals
    if sorted(pages) != list(range(len(pages))):
        raise ValueError(f"{defname}N pages are not numbered 0..{len(pages) - 1}")
    return [v for n in sorted(pages) for v in pages[n]]


def elf_raw_bytes(src):
    """The file a `<P>ElfRaw.lean` spells: rows of 32 bytes, big-endian, cut at elfSize."""
    size = int(re.search(r"^def elfSize : Nat := (\d+)", src, re.M).group(1))
    rows = _rows(src, "elfPage")
    data = b"".join(r.to_bytes(ROW, "big") for r in rows)
    if not (size <= len(data) < size + ROW):
        raise ValueError(f"elfSize {size} does not fit {len(rows)} rows")
    if any(data[size:]):
        raise ValueError("nonzero padding after elfSize")
    return data[:size]


def fs_img_bytes(src):
    """The image `Xv6/FsImgRaw.lean` spells: one big-endian Nat per 1024-byte block."""
    size = int(re.search(r"^def fsimgSize : Nat := (\d+)", src, re.M).group(1))
    blocks = _rows(src, "page")
    data = b"".join(b.to_bytes(BSIZE, "big") for b in blocks)
    if len(data) != size:
        raise ValueError(f"fsimgSize {size} but {len(blocks)} blocks")
    return data


# ---------------------------------------------------------------------------
# the checks
# ---------------------------------------------------------------------------

class Ctx:
    def __init__(self, repo, work, objdump, kernel, strict):
        self.repo, self.work, self.strict = repo, work, strict
        self.objdump = objdump if shutil.which(objdump) else None
        self.kernel = kernel
        self.results = []          # (name, status, detail)
        self.diffs = []            # (name, diff text)

    def src(self, rel):
        return os.path.join(self.repo, rel)

    def tool(self, name):
        return os.path.join(self.repo, "tools", name)

    def copy_in(self, rel):
        dst = os.path.join(self.work, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copyfile(self.src(rel), dst)
        return dst

    def run(self, argv):
        """Run a generator in the scratch tree; raises on a non-zero exit."""
        p = subprocess.run([sys.executable] + argv, cwd=self.work, capture_output=True, text=True)
        if p.returncode != 0:
            raise RuntimeError(f"{os.path.basename(argv[0])} failed:\n{p.stderr.strip()[-2000:]}")

    def compare(self, name, rels):
        """Diff scratch outputs against the tree.  -> list of differing files."""
        bad = []
        for rel in rels:
            want = _read(os.path.join(self.work, rel))
            have = _read(self.src(rel))
            if want != have:
                bad.append(rel)
                d = difflib.unified_diff(have.splitlines(), want.splitlines(),
                                         f"{rel} (checked in)", f"{rel} (regenerated)",
                                         lineterm="", n=1)
                self.diffs.append((name, "\n".join(list(d)[:60])))
        return bad

    def record(self, name, status, detail):
        self.results.append((name, status, detail))

    def regen(self, name, rels):
        bad = self.compare(name, rels)
        if bad:
            self.record(name, FAIL, "differs from its generator's output: " + ", ".join(bad))
        else:
            self.record(name, OK, ", ".join(rels))


def check_model_facts(c):
    c.copy_in("model/Lean_RV64D/LeanRV64D/PlatformConfig.lean")
    os.makedirs(os.path.join(c.work, "MachCSL"), exist_ok=True)
    c.run([c.tool("gen_model_facts.py")])
    c.regen("model-facts", ["MachCSL/ModelFacts.lean"])


def check_platform(c):
    c.copy_in("model/Lean_RV64D/LeanRV64D.lean")
    os.makedirs(os.path.join(c.work, "MachCSL"), exist_ok=True)
    c.run([c.tool("gen_platform.py")])
    c.regen("platform", ["MachCSL/Platform.lean"])


def check_kernel_tree(c):
    # gen_text_tree.py names the image in the header by the path it is given
    c.copy_in("Xv6/KernelImage.lean")
    c.run([c.tool("gen_text_tree.py"), "--image", "Xv6/KernelImage.lean",
           "--out", "Xv6/KernelTree.lean"])
    c.regen("kernel-tree", ["Xv6/KernelTree.lean"])


def check_user_text(c, P):
    # gen_user_text.py names the image in the Tree header by the path it is given
    c.copy_in(f"Xv6/User/{P}Image.lean")
    c.run([c.tool("gen_user_text.py"), "--image", f"Xv6/User/{P}Image.lean", "--module", P,
           "--outdir", "Xv6/User"])
    c.regen(f"user-text:{P}", [f"Xv6/User/{P}Tree.lean", f"Xv6/User/{P}Text.lean"])


def check_fs_img(c):
    rel = "Xv6/FsImgRaw.lean"
    _gen, source, rev, md5 = header(c.src(rel))
    img = fs_img_bytes(_read(c.src(rel)))
    got = hashlib.md5(img).hexdigest()
    if got != md5:
        c.record("fs-img", FAIL, f"{rel} spells an image with md5 {got}, its header says {md5}")
        return
    p = os.path.join(c.work, source)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    _write(p, img)
    os.makedirs(os.path.join(c.work, "Xv6"), exist_ok=True)
    c.run([c.tool("dump_fs_image.py"), "--img", source, "--rev", rev, "--out", rel])
    c.regen("fs-img", [rel])


def check_user_elf(c, P):
    name = f"user-elf:{P}"
    raw, img = f"Xv6/User/{P}ElfRaw.lean", f"Xv6/User/{P}Image.lean"
    _g, source, rev, md5 = header(c.src(raw))
    _g2, source2, rev2, md52 = header(c.src(img))
    elf = elf_raw_bytes(_read(c.src(raw)))
    got = hashlib.md5(elf).hexdigest()
    if got != md5:
        c.record(name, FAIL, f"{raw} spells a file with md5 {got}, its header says {md5}")
        return
    if (source, rev, md5) != (source2, rev2, md52):
        c.record(name, FAIL, f"{img} is a dump of {source2}@{rev2} (md5 {md52}), "
                             f"{raw} of {source}@{rev} (md5 {md5})")
        return
    if not c.objdump:
        c.record(name, FAIL if c.strict else SKIP,
                 f"md5 {md5} ok; no riscv objdump on PATH, so {P}Image.lean was not regenerated")
        return
    p = os.path.join(c.work, source)            # user/_<prog>
    os.makedirs(os.path.dirname(p), exist_ok=True)
    _write(p, elf)
    c.run([c.tool("dump_user_elf.py"), "--elf", source, "--module", P, "--rev", rev,
           "--outdir", "Xv6/User", "--objdump", c.objdump])
    c.regen(name, [img, raw, f"Xv6/User/{P}Tree.lean", f"Xv6/User/{P}Text.lean"])


def check_pins(c):
    """The image pins recorded in the generated headers agree (Rocq's
    xv6-rev-check warns when the checkout is not XV6_REV; here the pins live
    in the headers, and what can drift is one dump being redone alone)."""
    probs, pins = [], []
    kimg = header(c.src("Xv6/KernelImage.lean"))
    kelf = header(c.src("MachCSL/KernelElf.lean"))
    pins.append(f"kernel {kelf[2]} md5 {kelf[3]}")
    if kimg[2] != kelf[2]:
        probs.append(f"Xv6/KernelImage.lean is of xv6-riscv {kimg[2]}, MachCSL/KernelElf.lean of {kelf[2]}")
    fs = header(c.src("Xv6/FsImgRaw.lean"))
    pins.append(f"fs.img {fs[2]} md5 {fs[3]}")
    revs = set()
    for P in USER_PROGS:
        h = header(c.src(f"Xv6/User/{P}Image.lean"))
        revs.add(h[2])
        t = open(c.src(f"Xv6/User/{P}Tree.lean"), encoding="utf-8").readline()
        if f"Xv6/User/{P}Image.lean" not in t:
            probs.append(f"Xv6/User/{P}Tree.lean does not say it comes from {P}Image.lean")
    pins.append("user programs " + "/".join(sorted(revs)))
    if probs:
        c.record("pins", FAIL, "; ".join(probs))
    else:
        c.record("pins", OK, "; ".join(pins))


def check_kernel(c, explicit):
    name = "kernel"
    k = c.kernel
    if not k or not os.path.exists(k):
        why = (f"{k} does not exist" if explicit else
               "the kernel ELF is not checked in (xv6-riscv/ is .gitignored); the dumps are "
               "checked against each other by the build (Xv6.bootImage_wf)")
        c.record(name, FAIL if explicit else SKIP, why)
        return
    _g, source, rev, md5 = header(c.src("MachCSL/KernelElf.lean"))
    got = hashlib.md5(_read_bytes(k)).hexdigest()
    if got != md5:
        c.record(name, FAIL if explicit else SKIP,
                 f"{k} (md5 {got}) is not the pinned build (md5 {md5}, xv6-riscv {rev})")
        return
    if not c.objdump:
        c.record(name, FAIL if (explicit or c.strict) else SKIP, "no riscv objdump on PATH")
        return
    p = os.path.join(c.work, source)            # xv6-riscv/kernel/kernel, as the header names it
    os.makedirs(os.path.dirname(p), exist_ok=True)
    shutil.copyfile(k, p)
    for d in ("Xv6", "MachCSL"):
        os.makedirs(os.path.join(c.work, d), exist_ok=True)
    krev = header(c.src("Xv6/KernelImage.lean"))[2]
    c.run([c.tool("dump_kernel.py"), "--kernel", source, "--out", "Xv6/KernelImage.lean",
           "--rev", krev, "--objdump", c.objdump])
    # gen_kernel_data.py rewrites the byte lists of an existing file in place
    c.copy_in("Xv6/KernelData.lean")
    c.run([c.tool("gen_kernel_data.py"), "--kernel", source, "--out", "Xv6/KernelData.lean",
           "--objdump", c.objdump])
    c.run([c.tool("dump_elf_image.py"), "--kernel", source, "--out", "MachCSL/KernelElf.lean",
           "--rev", rev])
    c.regen(name, ["Xv6/KernelImage.lean", "Xv6/KernelTree.lean", "Xv6/KernelData.lean",
                   "MachCSL/KernelElf.lean"])


def all_checks(explicit_kernel):
    checks = [("pins", check_pins), ("model-facts", check_model_facts), ("platform", check_platform),
              ("kernel-tree", check_kernel_tree)]
    checks += [(f"user-text:{P}", lambda c, P=P: check_user_text(c, P)) for P in USER_PROGS]
    checks += [("fs-img", check_fs_img)]
    checks += [(f"user-elf:{P}", lambda c, P=P: check_user_elf(c, P)) for P in USER_PROGS]
    checks += [("kernel", lambda c: check_kernel(c, explicit_kernel))]
    return checks


def run_checks(c, only=None, explicit_kernel=False):
    for name, fn in all_checks(explicit_kernel):
        if only and not any(name == o or name.startswith(o + ":") for o in only):
            continue
        try:
            fn(c)
        except Exception as e:            # a generator that crashes is a failed check
            c.record(name, FAIL, f"{type(e).__name__}: {e}")
    return c


NOT_CHECKED = [
    ("model/Lean_RV64D/", "needs the patched `sail` compiler (tools/regen_sail_model.sh); "
                          "by hand: rerun it, then `git diff --exit-code model/`"),
    ("Xv6/Ush*Code.lean", "written by a lane script that was not kept; every fact is "
                          "re-proved from the image by the build"),
]


def render(c, fmt):
    n = {s: sum(1 for r in c.results if r[1] == s) for s in (OK, FAIL, SKIP)}
    out = []
    if fmt == "md":
        out.append("## Generated-file checks (`check-gen`)\n")
        out.append(f"**{n[OK]} ok · {n[FAIL]} failed · {n[SKIP]} skipped**\n")
        out.append("| check | status | detail |")
        out.append("|---|---|---|")
        mark = {OK: "ok", FAIL: ":x: FAIL", SKIP: "skipped"}
        for name, st, det in c.results:
            out.append(f"| `{name}` | {mark[st]} | {det.replace('|', chr(92) + '|')} |")
        out.append("")
        out.append("Not checked here: " + "; ".join(f"`{a}` ({b})" for a, b in NOT_CHECKED) + ".")
        for name, d in c.diffs:
            out.append(f"\n<details><summary>diff: {name}</summary>\n\n```diff\n{d}\n```\n</details>")
    else:
        for name, st, det in c.results:
            out.append(f"check-gen: {st:<4} {name:<22} {det}")
        for name, d in c.diffs:
            out.append(f"\n--- {name} ---\n{d}")
        for a, b in NOT_CHECKED:
            out.append(f"check-gen: n/a  {a:<22} {b}")
        out.append(f"check-gen: {n[OK]} ok, {n[FAIL]} failed, {n[SKIP]} skipped")
    return "\n".join(out)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--repo", default=REPO)
    ap.add_argument("--format", choices=("text", "md"), default="text")
    ap.add_argument("--out", help="write the report here as well as to stdout")
    ap.add_argument("--strict", action="store_true",
                    help="a check skipped for want of objdump is a failure")
    ap.add_argument("--kernel", help="the pinned kernel ELF (default: xv6-riscv/kernel/kernel "
                                     "if present and its md5 is the pinned one)")
    ap.add_argument("--objdump", default="riscv64-linux-gnu-objdump")
    ap.add_argument("--only", nargs="+", help="run only these checks (e.g. kernel-tree user-text)")
    ap.add_argument("--keep", help="leave the regenerated files in this directory")
    a = ap.parse_args(argv)

    repo = os.path.abspath(a.repo)
    kernel = os.path.abspath(a.kernel) if a.kernel else os.path.join(repo, "xv6-riscv/kernel/kernel")
    work = a.keep or tempfile.mkdtemp(prefix="check-gen-")
    os.makedirs(work, exist_ok=True)
    try:
        c = run_checks(Ctx(repo, os.path.abspath(work), a.objdump, kernel, a.strict),
                       only=a.only, explicit_kernel=bool(a.kernel))
    finally:
        if not a.keep:
            shutil.rmtree(work, ignore_errors=True)
    text = render(c, a.format)
    print(text)
    if a.out:
        with open(a.out, "w") as f:
            f.write(text + "\n")
    return 1 if any(st == FAIL for _, st, _ in c.results) else 0


if __name__ == "__main__":
    sys.exit(main())
